/// <summary>
/// MPJ_2677 - Kscerri - 10/06/2021
/// The <t>PurchReqTable</t> table extension
/// </summary>
[ExtensionOf(tableStr(PurchReqTable))]
final class METPurchReqTable_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// Find by purchreqId
    /// </summary>
    /// <param name = "_purchReqId">purchreqid</param>
    /// <returns>purchReqTable</returns>
    public static PurchReqTable findByPurchReqId(PurchReqId _purchReqId)
    {
        PurchReqTable purchReqTable;

        select firstonly purchReqTable
            where purchReqTable.PurchReqId == _purchReqId;

        return purchReqTable;
    }

    /// <summary>
    /// MPJ_2677 - Kscerri - 16/06/2021
    /// Customer account field validation
    /// </summary>
    /// <param name = "_fieldIdToCheck">checks current field</param>
    /// <returns>validation success</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean intRet = next ValidateField(_fieldIdToCheck);

        if (intRet)
        {
            switch (_fieldIdToCheck)
            {
                case fieldNum(PurchReqTable, METRDCustAccount):
                    if (this.BusinessJustification == CustParameters::find().METPRReason 
                        && !this.METRDCustAccount)
                    {
                        intRet = checkFailed("@MET:RetaiLDevCustAccountValidationMessage");
                    }
                    break;
                
                default :
                    break;
            }
        }

        return intRet;
    }

/// <summary>
/// MPJ_2677 - Kscerri - 16/06/2021
/// Display method cust name;
/// </summary>
/// <returns>cust name</returns>
public display Name displayMETCustName()
{
    return custTable::find(this.METRDCustAccount).name();
}
